.sliderValue'\n                @input='(e) => form.sliderValue = e.target.value'\n              )\n  article#tabs\n    section.card\n      h2.is-title-2.card-header Tabs\n\n      p Todo: replace with component once created\n      table\n        thead\n          th code\n          th demo\n        tr\n          td\n            pre\n              | nav.tabs\n              br\n              | button.is-unstyled.tabs-link tab1\n              br\n              | button.is-unstyled.tabs-link.tabs-link-active\n              br\n              |   | tab2\n              br\n              |   span.tabs-notification 3\n          td\n            br\n            nav.tabs\n              button.is-unstyled.tabs-link tab1\n              button.is-unstyled.tabs-link.tabs-link-active\n                | tab2\n                span.tabs-notification 3\n\n  article#stepper\n    section.card\n      h2.is-title-2.card-header Stepper\n\n      p Todo: replace with component once created\n      table\n        thead\n          th code\n          th demo\n        tr\n          td\n            pre\n              | .steps\n              br\n              |   button.step 1\n              br\n              |   button.step.active 2\n              br\n              |   button.step.next 3\n          td\n            .steps\n              button.step 1\n              button.step.active 2\n              button.step.next 3\n  article#menu\n    section.card\n      h2.is-title-2.card-header Menu\n      table\n        thead\n          th code\n          th demo\n        tr\n          td\n            pre\n              | menu-parent\n              |   menu-trigger.is-icon-small(\n              |    :aria-label='L(\"Show info\")\n              |   )\n              |     i.icon-ellipsis-v\n              |   menu-content\n              |     menu\n              |       menu-item(\n              |         tag='button'\n              |         item-id='profile'\n              |         icon='info'\n              |       ) Edit profile\n          td\n            menu-parent\n              menu-trigger.is-icon-small(:aria-label='L(\"Show info\")')\n                i.icon-ellipsis-v\n\n              menu-content.c-menu-content\n                menu\n                  menu-item(\n                    tag='button'\n                    item-id='profile'\n                    icon='pencil-alt'\n                  ) Edit profile\n\n                  menu-item(\n                    tag='button'\n                    item-id='message'\n                    icon='comment'\n                  ) Send message\n        tr\n          td\n            pre\n              | button-dropdown-menu(\n              |   :buttonText='L(\"Create proposal\")'\n              |   :options='buttonDropdownMenuOpts'\n              | )\n          td\n            button-dropdown-menu(\n              :buttonText='L(\"Create proposal\")'\n              :options='config.buttonDropdownMenuOpts'\n              @select='onButtonDropdownItemSelect'\n            )\n  article#modals\n    section.card\n      h2.is-title-2.card-header Modals\n      h3.is-title-3 Modal standard\n      p See the modal demo to know what things can be customized. A modal can also be opened on top of another modal.\n      br\n      table\n        thead\n          th code\n          th demo\n        tr\n          td\n            code\n              | sbp('okTurtles.events/emit',\n              br\n              |   OPEN_MODAL, 'DSModalNested'\n              br\n              | )\n          td\n            button.is-outlined(@click='openModal(\"DSModalNested\")')\n              i18n Open Modal\n\n      h3.is-title-3 Modal fullscreen\n      p This modal only contain opening and closing mechanism (shared with the modal in modal mixin).\n      br\n      table\n        thead\n          th code\n          th demo\n        tr\n          td\n            p A fullscreen modal.\n            code\n              | sbp('okTurtles.events/emit',\n              br\n              |   OPEN_MODAL, 'DSModalFullscreen'\n              br\n              | )\n          td\n            button.is-outlined(@click='openModal(\"DSModalFullscreen\")')\n              i18n Open Modal\n\n      h3.is-title-3 Modal with Query\n      p Some modals need \"context\" to be displayed. We pass that data through URL queries.\n      br\n      table\n        thead\n          th code\n          th demo\n        tr\n          td\n            code\n              | sbp('okTurtles.events/emit',\n              br\n              |  OPEN_MODAL, 'DSModalQuery', { name: \"John\"}\n              br\n              | )\n          td\n            .buttons\n              button.is-outlined(@click='openModal(\"DSModalQuery\", { name: \"John\"})')\n                i18n Open Modal \"John\"\n\n              button.is-outlined(@click='openModal(\"DSModalQuery\", { name: \"Kate\"})')\n                i18n Open Modal \"Kate\"\n\n  article#prompts\n    section.card\n      h2.is-title-2.card-header Prompts\n      p To call a prompt with yes / no question we need to call sbp with this format:\n      br\n      table\n        thead\n          th code\n          th demo\n        tr\n          td\n            code\n              | const boolYesOrNo =\n              br\n              | await sbp('gi.ui/prompt', {\n              br\n              | &nbsp question: 'Tacos?',\n              br\n              | &nbsp  heading: 'Update info',\n              br\n              | &nbsp  primaryButton: 'Yes',\n              br\n              | &nbsp  secondaryButton: 'No'\n              br\n              | })\n          td\n            button.is-outlined(@click='openPrompt()')\n              i18n Open Prompt\n\n      p *primaryButton and secondaryButton parameters are optional\n\n  article#clipboard-uis\n    section.card\n      h2.is-title-2.card-header Clipboard tools\n      p UI elements to use for copying a text or link into the clipboard of user's device.\n      br\n      br\n\n      h3.is-title-3 Link to copy\n      br\n      table\n        thead\n          th code\n          th demo\n        tr\n          td.c-top\n            pre\n              | link-to-copy.c-link(link='string')\n          td\n            link-to-copy.c-link(link='/app/join?groupId=21XWnNJvq9&secret=3763')\n\n      br\n      h3.is-title-3 Copyable input\n      br\n      table\n        thead\n          th code\n          th demo\n        tr\n          td.c-top\n            pre\n              | copyable-input(v-model='form.copyableInput')\n          td\n            copyable-input(\n              v-model='form.copyableInput'\n            )\n\n  article#Illustrations\n    section.card\n      h2.is-title-2.card-header Illustrations (SVGs)\n      p We have a good amount of nice illustrations across Group Income. Those illustrations' colors need to be customized based on the current theme. For that reason we display them in inline SVGs.\n      br\n      p Here's how you can load a SVG:\n      br\n      table.c-svgTable\n        thead\n          th code\n          th demo\n        tr\n          td.c-top\n            pre\n              | svg-hello\n              |\n              | import SvgHello from '../../../frontend/assets/svgs/hello.svg'\n          td\n            svg-hello.c-svg\n      br\n      br\n\n      p Know more about how all of this works at #[pre(style='display:inline') assets/svg/README.md]\n      br\n      b.is-title-4 Available SVGs:\n      .c-svgList\n        .c-svgList-item(\n          v-for='svg in config.svgs'\n          :key='svg.name'\n          )\n          component.c-svg(:is='svg.component')\n          .c-svgList-text\n            p #[b Name]: {{svg.name}}\n\n  article#qrcode\n    section.card\n      h2.is-title-2.card-header QR Code\n      p We have a component named 'QrCode' that uses 'qrious' to encode a string into a qr-code image.\n      br\n      table\n        thead\n          th code\n          th demo\n        tr\n          td.c-top\n            pre\n              | qr-code(\n              |   value='https://groupincome.org/community/'\n              |   :sideLength='88'\n              | )\n          td\n            qr-code(\n              value='https://groupincome.org/community/'\n              :sideLength='88'\n            )\n      br\n      br\n</template>\n\n<script>\nimport sbp from '@sbp/sbp'\nimport '../../../frontend/views/utils/ui.js'\nimport Page from '../../../frontend/views/components/Page.vue'\nimport Badge from '../../../frontend/views/components/Badge.vue'\nimport BannerSimple from '../../../frontend/views/components/banners/BannerSimple.vue'\nimport BannerScoped from '../../../frontend/views/components/banners/BannerScoped.vue'\nimport ButtonSubmit from '../../../frontend/views/components/ButtonSubmit.vue'\nimport CalloutCard from '../../../frontend/views/components/CalloutCard.vue'\nimport LinkToCopy from '../../../frontend/views/components/LinkToCopy.vue'\nimport CopyableInput from '../../../frontend/views/components/CopyableInput.vue'\nimport QrCode from '../../../frontend/views/components/QrCode.vue'\nimport { MenuParent, MenuTrigger, MenuContent, MenuItem, MenuHeader } from '../../../frontend/views/components/menu/index.js'\nimport Tooltip from '../../../frontend/views/components/Tooltip.vue'\nimport SliderContinuous from '../../../frontend/views/components/SliderContinuous.vue'\nimport Search from '../../../frontend/views/components/Search.vue'\nimport UsersSelector from '../../../frontend/views/components/UsersSelector.vue'\nimport ButtonDropdownMenu from '../../../frontend/views/components/ButtonDropdownMenu.vue'\nimport { OPEN_MODAL } from '../../../frontend/utils/events.js'\nimport SvgAccess from '../../../frontend/assets/svgs/access.svg'\nimport SvgBitcoin from '../../../frontend/assets/svgs/bitcoin.svg'\nimport SvgBrokenLink from '../../../frontend/assets/svgs/broken-link.svg'\nimport SvgContributions from '../../../frontend/assets/svgs/contributions.svg'\nimport SvgConversation from '../../../frontend/assets/svgs/conversation.svg'\nimport SvgCreateGroup from '../../../frontend/assets/svgs/create-group.svg'\nimport SvgHello from '../../../frontend/assets/svgs/hello.svg'\nimport SvgInvitation from '../../../frontend/assets/svgs/invitation.svg'\nimport SvgJoinGroup from '../../../frontend/assets/svgs/join-group.svg'\nimport SvgMoney from '../../../frontend/assets/svgs/money.svg'\nimport SvgProposal from '../../../frontend/assets/svgs/proposal.svg'\nimport SvgVote from '../../../frontend/assets/svgs/vote.svg'\nimport SvgAttachment from '../../../frontend/assets/svgs/attachment.svg'\nimport { mapGetters, mapMutations } from 'vuex'\nimport { THEME_LIGHT, THEME_DARK } from '../../../frontend/model/settings/themes.js'\n\nexport default ({\n  name: 'DesignSystemView',\n  data () {\n    return {\n      articles: [],\n      config: {\n        SvgVote,\n        colors: [\n          {\n            name: 'primary',\n            usage: 'Used on main decorative / interactive elements.'\n          },\n          {\n            name: 'success',\n            usage: 'Used on elements to show something good happened - Do not mix its usage with success (same color in this theme but with  different meanings)'\n          },\n          {\n            name: 'warning',\n            usage: 'Used on elements to show something not that good happened - Do not mix its usage with $tertiary (same color in this theme but with different meanings)'\n          },\n          {\n            name: 'danger',\n            usage: 'Used on elements to show something wrong happened'\n          },\n          {\n            name: 'general',\n            usage: 'Used on backgrounds and interactions'\n          },\n          {\n            name: 'text',\n            usage: 'Used on text elements'\n          }\n        ],\n        svgs: [\n          {\n            component: SvgAccess,\n            name: 'SvgAccess',\n            sprite: 'Dashboard'\n          },\n          {\n            component: SvgBitcoin,\n            name: 'SvgBitcoin',\n            sprite: 'IncomeDetails'\n          },\n          {\n            component: SvgBrokenLink,\n            name: 'SvgBrokenLink',\n            sprite: 'Newcomers'\n          },\n          {\n            component: SvgContributions,\n            name: 'SvgContributions',\n            sprite: 'Dashboard'\n          },\n          {\n            component: SvgConversation,\n            name: 'SvgConversation',\n            sprite: 'Dashboard'\n          },\n          {\n            component: SvgCreateGroup,\n            name: 'SvgCreateGroup',\n            sprite: 'Newcomers'\n          },\n          {\n            component: SvgHello,\n            name: 'SvgHello',\n            sprite: 'IncomeDetails'\n          },\n          {\n            component: SvgInvitation,\n            name: 'SvgInvitation',\n            sprite: 'Newcomers'\n          },\n          {\n            component: SvgJoinGroup,\n            name: 'SvgJoinGroup',\n            sprite: 'Newcomers'\n          },\n          {\n            component: SvgMoney,\n            name: 'SvgMoney',\n            sprite: 'IncomeDetails'\n          },\n          {\n            component: SvgProposal,\n            name: 'SvgProposal',\n            sprite: 'Dashboard'\n          },\n          {\n            component: SvgVote,\n            name: 'SvgVote',\n            sprite: 'Dashboard'\n          },\n          {\n            component: SvgAttachment,\n            name: 'SvgAttachment',\n            sprite: 'Chat'\n          }\n        ],\n        buttonDropdownMenuOpts: [\n          { type: 'header', name: 'Group Members' },\n          { type: 'item', id: 'add-new-member', name: 'Add new member', icon: 'comment' },\n          { type: 'item', id: 'remove-member', name: 'Remove member', icon: 'comment' },\n          { type: 'header', name: 'Voting Systems' },\n          { type: 'item', id: 'change-disagreeing-number', name: 'Change disagreeing number', icon: 'comment' },\n          { type: 'item', id: 'change-voting-threshold', name: 'Change voting threshold', icon: 'comment' }\n        ]\n      },\n      form: {\n        searchValue: '',\n        searchUserIDs: [],\n        selectPayment: 'choose',\n        copyableInput: '',\n        sliderValue: 25\n      },\n      ephemeral: {\n        passwordHidden: true,\n        forms: {\n          hasError: false,\n          isDisabled: false\n        }\n      }\n    }\n  },\n  components: {\n    Page,\n    Badge,\n    BannerSimple,\n    BannerScoped,\n    ButtonSubmit,\n    CalloutCard,\n    LinkToCopy,\n    CopyableInput,\n    QrCode,\n    MenuParent,\n    MenuTrigger,\n    MenuContent,\n    MenuHeader,\n    MenuItem,\n    ButtonDropdownMenu,\n    Search,\n    UsersSelector,\n    Tooltip,\n    SvgHello,\n    SliderContinuous\n  },\n  mounted () {\n    const menu = document.getElementById('c-design-system-sidebar')\n    menu.parentElement.setAttribute('style', 'position: fixed')\n    document.querySelectorAll('article').forEach((el) => {\n      const link = document.createElement('A')\n      link.appendChild(document.createTextNode(el.querySelector('h2').innerHTML))\n      link.setAttribute('href', `#${el.id}`)\n      menu.appendChild(link)\n      this.articles.push({\n        link: link,\n        top: el.getBoundingClientRect().top - window.innerHeight\n      })\n    })\n\n    document.querySelectorAll('.l-page')[0].addEventListener('scroll', this.handleScroll)\n\n    // Keep the position of the current element you're working on\n    const hash = document.location.hash\n    if (hash) {\n      document.querySelector(hash).scrollIntoView()\n    }\n  },\n  destroyed () {\n    window.removeEventListener('scroll', this.handleScroll)\n  },\n  methods: {\n    ...mapMutations([\n      'setTheme'\n    ]),\n    login () {\n      console.error('unimplemented, try using the actual Login.vue modal')\n    },\n    openModal (name, queries) {\n      sbp('okTurtles.events/emit', OPEN_MODAL, 